package com.clipboardfix

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import java.util.Base64

/**
 * 由 Java 版 PinCancelIcon 等价迁移；PNG_BASE64 与原版逐字节一致。
 */
object PinCancelIcon {

    private const val PNG_BASE64 =
        """"""

    @Volatile
    private var cached: Bitmap? = null

    /** 取图标位图（首次调用时解码，之后走缓存）。解码失败返回 null。 */
    @JvmStatic
    fun get(): Bitmap? {
        val b = cached
        if (b != null) return b
        val decoded = try {
            val raw = Base64.getDecoder().decode(PNG_BASE64)
            BitmapFactory.decodeByteArray(raw, 0, raw.size)
        } catch (_: Throwable) {
            null
        }
        cached = decoded
        return decoded
    }
}
